// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data, address caller) public {
        vm.assume(caller != address(0));
        uint256 beforeCount = c.depositsCount();
        vm.deal(caller, value);
        vm.prank(caller);
        bool ok;
        try c.sendMoney(target, value, data) { ok = true; } catch { ok = false; }
        if (ok) {
            assertTrue(caller == c.owner());
        } else {
            assertEq(c.depositsCount(), beforeCount);
        }
    }
}
